class Solution {
public:
    int maximumSaleItems(vector<vector<int>>& items, int budget) {
        int n = items.size();
        vector<int> cnt(n + 1, 0);
        for (auto& it : items) cnt[it[0]]++;

        vector<long long> mult(n + 1, 0);
        for (int f = 1; f <= n; f++) {
            if (cnt[f] == 0) continue;
            for (int j = f; j <= n; j += f) mult[f] += cnt[j];
        }

        long long m = LLONG_MAX;
        vector<pair<int, long long>> batches;
        batches.reserve(n);
        for (auto& it : items) {
            m = min(m, (long long)it[1]);
            long long g = mult[it[0]] - 1;
            if (g > 0) batches.push_back({it[1], g});
        }
        sort(batches.begin(), batches.end());

        long long B = budget;
        long long ans = B / m;
        long long k = 0, cum = 0;
        for (auto& pr : batches) {
            int p = pr.first;
            long long g = pr.second;
            ans = max(ans, 2 * k + (B - cum) / m);
            if (cum + (long long)p > B) break;
            long long t = min(g, (B - cum) / p);
            ans = max(ans, 2 * (k + t) + (B - cum - t * p) / m);
            k += t;
            cum += t * p;
            if (t < g) break;
        }
        return (int)ans;
    }
};
